import subprocess, os
def run_script(cmd, term="xterm", timeout=6):
    env=os.environ.copy(); env["TERM"]=term
    try:
        p=subprocess.run(["script","-qec", cmd, "/dev/null"], capture_output=True, env=env, timeout=timeout)
        return p.stdout, p.stderr, p.returncode, False
    except subprocess.TimeoutExpired as e:
        return e.stdout or b"", e.stderr or b"", None, True

tests = [
    "printf 'hello\\nworld\\n' | ./executable --select-all --query hello > /tmp/peco_out; echo RC:$?; echo OUT:; cat /tmp/peco_out | od -c",
