                    else:
                        opts[canon] = val
                    i += 1
                    continue
            else:
                name = body
                if name not in LONG_TO_CANON:
                    return flag_error(f"unknown flag `{name}'")
                canon = LONG_TO_CANON[name]
                if canon in BOOL_FLAGS:
                    opts[canon] = True
                    i += 1
                    continue
                else:
                    # need next token as value
                    if i+1 >= n:
                        return flag_error(f"expected argument for flag `{display_name(canon)}'")
                    nxt = args[i+1]
                    if is_option_like(nxt):
                        return flag_error(f"expected argument for flag `{display_name(canon)}', but got option `{nxt}'")
                    # nxt is value (even if it's "-" or "--"? Those are not option-like, so value)
                    val = nxt
                    if canon in INT_FLAGS:
                        v, errkind = parse_go_int(val)
                        if errkind:
                            return flag_error(f"invalid argument for flag `{display_name(canon)}' (expected int): strconv.ParseInt: parsing \"{val}\": {errkind}")
                        opts[canon] = v
                    else:
                        opts[canon] = val
                    i += 2
                    continue
        else:
            # short flag(s): tok starts with single "-" (len>1, not "--", not "-")
            # tok like "-h", "-b10", "-b=10", "-hfoo", "-hb", etc.
            # Process chars after "-"
            short_body = tok[1:]
