            # We need to handle that "-hfoo" means -h + -f + ...
            # "-b10" means -b with value "10"
            # "-b=10" means -b with value "10" (strip "=")
            # To do this, iterate j over short_body
            pos = 0
            consumed_next = False
            # We'll handle one token's shorts in loop, but need to know if we consumed next arg
            # Use while pos < len(short_body)
            error = None
            next_i = i+1
            # Temporary: we need to process all shorts in this token
            # For simplicity, process first char, if it's 'b' with remainder, consume remainder as value and break (no further shorts in same token)
            # If first char is 'h', consume it as bool, then continue with remainder as new shorts in same token
            # Example "-hb": first 'h' bool, remainder "b" -> process 'b' with no remainder, need next token
            # Example "-bh": first 'b' with remainder "h" -> value "h", done (no further)
            # Example "-hfoo": first 'h', remainder "foo" -> process 'f' unknown => error
            # So loop:
            k = 0
            while k < len(short_body):
                ch = short_body[k]
                if ch not in SHORT_MAP:
                    return flag_error(f"unknown flag `{ch}'")
                canon = SHORT_MAP[ch]
                if canon in BOOL_FLAGS:
                    opts[canon] = True
                    k += 1
                    continue
                else:
                    # takes arg: remainder is short_body[k+1:]
                    rem = short_body[k+1:]
                    if rem != "":
                        # strip leading "=" if present? For "-b=10", rem is "=10", value should be "10"
                        if rem.startswith("="):
                            rem = rem[1:]
                        val = rem
