{"command": "cat > main.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

const helpText = "\nUsage: peco [options] [FILE]\n\nOptions:\n  -h, --help            show this help message and exit\n  --query               initial value for query\n  --rcfile              path to the settings file\n  --version             print the version and exit\n  -b, --buffer-size     number of lines to keep in search buffer\n  --null                expect NUL (\\0) as separator for target/output\n  --initial-index       position of the initial index of the selection (0 base)\n  --initial-filter      specify the default filter\n  --prompt              specify the prompt string\n  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'\n  --select-1            select first item and immediately exit if the input contains only 1 item\n  --exit-0              exit immediately with status 1 if the input is empty\n  --select-all          select all items and immediately exit\n  --on-cancel           specify action on user cancel. 'success' or 'error'.\n                        default is 'success'. This may change in future versions\n  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.\n                        default is to use colors. This option is experimental\n  --exec                execute command instead of finishing/terminating peco.\n                        Please note that this command will receive selected line(s) from stdin,\n                        and will be executed via '/bin/sh -c' or 'cmd /c'\n  --print-query         print out the current query as first line of output\n  --ansi                enable ANSI color code support\n  --height              display height in lines or percentage (e.g. '10', '50%')\n"
const versionText = "peco version v0.5.11 (built with go1.25.0)\n"

var longToCanon = map[string]string{
	"help": "help", "query": "query", "rcfile": "rcfile", "version": "version",
	"buffer-size": "buffer-size", "null": "null", "initial-index": "initial-index",
	"initial-filter": "initial-filter", "prompt": "prompt", "layout": "layout",
	"select-1": "select-1", "exit-0": "exit-0", "select-all": "select-all",
	"on-cancel": "on-cancel", "selection-prefix": "selection-prefix", "exec": "exec",
	"print-query": "print-query", "ansi": "ansi", "height": "height",
}
var boolFlags = map[string]bool{"help": true, "version": true, "null": true, "select-1": true, "exit-0": true, "select-all": true, "print-query": true, "ansi": true}
var intFlags = map[string]bool{"buffer-size": true, "initial-index": true}
var shortMap = map[byte]string{'h': "help", 'b': "buffer-size"}

func displayName(canon string) string {
	if canon == "help" {
		return "-h, --help"
	}
	if canon == "buffer-size" {
		return "-b, --buffer-size"
	}
	return "--" + canon
}

func isOptionLike(tok string, forInt bool) bool {
	if len(tok) <= 1 {
		return false
	}
	if !strings.HasPrefix(tok, "-") {
		return false
	}
	if tok == "--" {
		return false
	}
	if forInt {
		if len(tok) >= 2 && tok[1] >= '0' && tok[1] <= '9' {
			return false
		}
	}
	return true
}

type Options struct {
	Help bool
	Query *string
	Rcfile *string
	Version bool
	BufferSize *int
	Null bool
	InitialIndex *int
	InitialFilter *string
	Prompt *string
	Layout *string
	Select1 bool
	Exit0 bool
	SelectAll bool
	OnCancel *string
	SelectionPrefix *string
	Exec *string
	PrintQuery bool
	Ansi bool
	Height *string
}

func flagError(msg string) (Options, []string, string) {
	h := helpText
	if strings.HasPrefix(h, "\n") {
		h = h[1:]
	}
	full := msg + "\n\n" + h + "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: " + msg + "\n"
	return Options{}, nil, full
}

func parseArgs(argv []string) (Options, []string, string) {
	var opts Options
	var positionals []string
	args := argv[1:]
	n := len(args)
	i := 0
	for i < n {
		tok := args[i]
		if tok == "-" || tok == "--" || !strings.HasPrefix(tok, "-") {
			positionals = append(positionals, tok)
			i++
			continue
		}
		if strings.HasPrefix(tok, "--") {
			body := tok[2:]
			if strings.Contains(body, "=") {
				parts := strings.SplitN(body, "=", 2)
				name := parts[0]
				val := parts[1]
				canon, ok := longToCanon[name]
				if !ok {
					o, p, e := flagError(fmt.Sprintf("unknown flag `%s'", name))
					_ = o
					_ = p
					return o, p, e
				}
				if boolFlags[canon] {
					o, p, e := flagError(fmt.Sprintf("bool flag `%s' cannot have an argument", displayName(canon)))
					return o, p, e
