					case "select-1":
						opts.Select1 = true
					case "exit-0":
						opts.Exit0 = true
					case "select-all":
						opts.SelectAll = true
					case "print-query":
						opts.PrintQuery = true
					case "ansi":
						opts.Ansi = true
					}
					i++
					continue
				} else {
					if i+1 >= n {
						o, p, e := flagError(fmt.Sprintf("expected argument for flag `%s'", displayName(canon)))
						return o, p, e
