						case "height":
							opts.Height = &s
						}
					}
					i++
					continue
				}
			} else {
				name := body
				canon, ok := longToCanon[name]
				if !ok {
					o, p, e := flagError(fmt.Sprintf("unknown flag `%s'", name))
					return o, p, e
				}
				if boolFlags[canon] {
					switch canon {
					case "help":
						opts.Help = true
					case "version":
						opts.Version = true
					case "null":
						opts.Null = true
					case "select-1":
						opts.Select1 = true
					case "exit-0":
						opts.Exit0 = true
					case "select-all":
						opts.SelectAll = true
					case "print-query":
						opts.PrintQuery = true
					case "ansi":
						opts.Ansi = true
					}
					i++
					continue
				} else {
					if i+1 >= n {
						o, p, e := flagError(fmt.Sprintf("expected argument for flag `%s'", displayName(canon)))
						return o, p, e
					}
					nxt := args[i+1]
					forInt := intFlags[canon]
					if isOptionLike(nxt, forInt) {
						o, p, e := flagError(fmt.Sprintf("expected argument for flag `%s', but got option `%s'", displayName(canon), nxt))
						return o, p, e
					}
					val := nxt
					if intFlags[canon] {
						v, err := strconv.ParseInt(val, 0, 64)
						if err != nil {
							o, p, e := flagError(fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": %s", displayName(canon), val, parseIntErrKind(err)))
							return o, p, e
						}
						iv := int(v)
						if canon == "buffer-size" {
							opts.BufferSize = &iv
						} else if canon == "initial-index" {
							opts.InitialIndex = &iv
						}
					} else {
						s := val
						switch canon {
						case "query":
							opts.Query = &s
						case "rcfile":
							opts.Rcfile = &s
						case "initial-filter":
							opts.InitialFilter = &s
						case "prompt":
							opts.Prompt = &s
						case "layout":
							opts.Layout = &s
						case "on-cancel":
							opts.OnCancel = &s
						case "selection-prefix":
							opts.SelectionPrefix = &s
						case "exec":
							opts.Exec = &s
						case "height":
							opts.Height = &s
						}
					}
					i += 2
					continue
				}
			}
		} else {
			shortBody := tok[1:]
			nextI := i + 1
			k := 0
			for k < len(shortBody) {
				ch := shortBody[k]
				canon, ok := shortMap[ch]
				if !ok {
					o, p, e := flagError(fmt.Sprintf("unknown flag `%c'", ch))
					return o, p, e
				}
				if boolFlags[canon] {
					remAfter := shortBody[k+1:]
					if strings.HasPrefix(remAfter, "=") {
						o, p, e := flagError(fmt.Sprintf("bool flag `%s' cannot have an argument", displayName(canon)))
						return o, p, e
					}
					if canon == "help" {
						opts.Help = true
					}
					k++
					continue
				} else {
					rem := shortBody[k+1:]
					if rem != "" {
						if strings.HasPrefix(rem, "=") {
							rem = rem[1:]
						}
						val := rem
						v, err := strconv.ParseInt(val, 0, 64)
						if err != nil {
							o, p, e := flagError(fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": %s", displayName(canon), val, parseIntErrKind(err)))
							return o, p, e
						}
						iv := int(v)
						if canon == "buffer-size" {
							opts.BufferSize = &iv
						}
						k = len(shortBody)
						break
					} else {
						if nextI >= n {
							o, p, e := flagError(fmt.Sprintf("expected argument for flag `%s'", displayName(canon)))
							return o, p, e
						}
						nxt := args[nextI]
						if isOptionLike(nxt, true) {
							o, p, e := flagError(fmt.Sprintf("expected argument for flag `%s', but got option `%s'", displayName(canon), nxt))
							return o, p, e
						}
						val := nxt
						v, err := strconv.ParseInt(val, 0, 64)
						if err != nil {
							o, p, e := flagError(fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": %s", displayName(canon), val, parseIntErrKind(err)))
							return o, p, e
						}
						iv := int(v)
						if canon == "buffer-size" {
							opts.BufferSize = &iv
						}
						nextI++
						k = len(shortBody)
						break
					}
				}
			}
			if nextI != i+1 {
				i = nextI
			} else {
				i++
			}
			continue
		}
	}
	return opts, positionals, ""
}

func parseIntErrKind(err error) string {
	s := err.Error()
	// Go's strconv errors are like: strconv.ParseInt: parsing "x": invalid syntax (but err already is that? Actually err.Error() is `strconv.ParseInt: parsing "x": invalid syntax`? No, when we call ParseInt, err.Error() is `strconv.ParseInt: parsing "x": invalid syntax`? Let's check: ParseInt returns error with message `strconv.ParseInt: parsing "x": invalid syntax`? Actually no, it returns `strconv.NumError` with message? We need to extract kind.
	// Simpler: check if contains "out of range" vs "invalid syntax"
	if strings.Contains(s, "out of range") {
		return "value out of range"
	}
	return "invalid syntax"
}

func main() {
	opts, positionals, errmsg := parseArgs(os.Args)
	if errmsg != "" {
		fmt.Fprint(os.Stderr, errmsg)
		os.Exit(1)
	}
	if opts.Layout != nil {
		if *opts.Layout != "top-down" && *opts.Layout != "bottom-up" && *opts.Layout != "top-down-query-bottom" {
			fmt.Fprintf(os.Stderr, "Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line arguments: unknown layout: '%s'\n", *opts.Layout)
			os.Exit(1)
		}
	}
	if opts.Help {
		fmt.Fprint(os.Stdout, helpText)
		os.Exit(0)
	}
	if opts.Version {
		fmt.Fprint(os.Stdout, versionText)
		os.Exit(0)
	}
	fmt.Fprint(os.Stderr, "Error: failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set\n")
	os.Exit(1)
}
