		// We can implement Unmarshal that first tries to unmarshal as string, and if fails, return error that mimics Go's default? Hmm.
		return err
	}
	if s != "success" && s != "error" {
		return fmt.Errorf("invalid OnCancel value %q: must be \"success\" or \"error\"", s)
	}
	*o = OnCancelBehavior(s)
	return nil
}

