func (s *StyleSet) UnmarshalJSON(data []byte) error {
	// Custom to produce "failed to unmarshal Style: ..." prefix? Actually original error for Style with number? Let's see: Style as number 123 gave "of type config.StyleSet" (not custom prefix). For Style with {"Basic": 123}, error was "failed to unmarshal Style: json: cannot unmarshal number into Go value of type []string"
	// That suggests StyleSet has custom Unmarshal that wraps inner errors with "failed to unmarshal Style: ".
