func findConfigFile(rcfile *string) (string, bool) {
    if rcfile != nil {
        return *rcfile, true
    }
    // Search default locations
    // 1. $XDG_CONFIG_HOME/peco/config.json or yaml
    // 2. $HOME/.config/peco/config.json or yaml
    // 3. $XDG_CONFIG_DIRS/peco/config.json or yaml for each dir
    // 4. $HOME/.peco/config.json or yaml
    home := os.Getenv("HOME")
    xdgHome := os.Getenv("XDG_CONFIG_HOME")
    candidates := []string{}
    if xdgHome != "" {
        candidates = append(candidates, xdgHome+"/peco/config.json", xdgHome+"/peco/config.yaml", xdgHome+"/peco/config.yml")
    } else if home != "" {
        candidates = append(candidates, home+"/.config/peco/config.json", home+"/.config/peco/config.yaml", home+"/.config/peco/config.yml")
    } else {
        candidates = append(candidates, os.ExpandEnv("$HOME/.config/peco/config.json"))
    }
    // XDG_CONFIG_DIRS
    xdgDirs := os.Getenv("XDG_CONFIG_DIRS")
    var dirs []string
    if xdgDirs == "" {
        dirs = []string{"/etc/xdg"}
    } else {
        dirs = strings.Split(xdgDirs, ":")
    }
    for _, d := range dirs {
        if d == "" {
            continue
        }
        candidates = append(candidates, d+"/peco/config.json", d+"/peco/config.yaml", d+"/peco/config.yml")
    }
    if home != "" {
        candidates = append(candidates, home+"/.peco/config.json", home+"/.peco/config.yaml", home+"/.peco/config.yml")
    }
    // Also try $HOME/.config... already? Need to handle case where XDG_CONFIG_HOME set but also need $HOME/.config? README says 2 is $XDG_CONFIG_HOME, 3 is $HOME/.config, 4 is XDG_CONFIG_DIRS. So if XDG_CONFIG_HOME is set, we should still try $HOME/.config as well? Actually README lists them as separate, so we should try both regardless.
    // To be safe, add $HOME/.config even if XDG set and not already added
    if xdgHome != "" && home != "" {
        extra := []string{home + "/.config/peco/config.json", home + "/.config/peco/config.yaml", home + "/.config/peco/config.yml"}
        // Insert after first 3?
        // Simplify: just append if not already in candidates
        for _, e := range extra {
            found := false
            for _, c := range candidates {
                if c == e {
                    found = true
                    break
                }
            }
            if !found {
                candidates = append(candidates, e)
            }
        }
    }
    for _, p := range candidates {
        if _, err := os.Stat(p); err == nil {
            return p, true
        }
    }
    return "", false
}

