	return ansiRe.ReplaceAllString(s, "")
}

func parseHeightSpec(s string) (interface{}, error) {
	if s == "" {
		return nil, nil
	}
	if strings.HasSuffix(s, "%") {
		num := s[:len(s)-1]
		if num == "" {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		// Must be decimal integer, no hex, no underscores, no spaces
		if strings.TrimSpace(num) != num {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		if strings.Contains(num, "_") || strings.Contains(num, "x") || strings.Contains(num, "X") || strings.Contains(num, ".") {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		// Check valid integer (allow leading + -? Probably not for percent, but handle)
