		if err != nil {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		_ = v
		return s, nil
	} else {
		if strings.TrimSpace(s) != s {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		if strings.Contains(s, "_") || strings.Contains(s, "x") || strings.Contains(s, "X") || strings.Contains(s, ".") {
			// Actually "0x10" for height? Probably invalid, since height is decimal. Our earlier test for height "bogus" invalid, but "10" valid. What about "0x10"? Likely invalid. Good.
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		v, err := strconv.Atoi(s)
		if err != nil {
			return nil, fmt.Errorf("invalid height specification: %q", s)
		}
		_ = v
		return s, nil
	}
}
