	if s == "" {
		return nil
	}
	if strings.HasSuffix(s, "%") {
		num := s[:len(s)-1]
		if num == "" {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		if strings.TrimSpace(num) != num {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		if strings.Contains(num, "_") || strings.Contains(num, ".") || strings.Contains(strings.ToLower(num), "x") {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		if _, err := strconv.Atoi(num); err != nil {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		return nil
	} else {
		if strings.TrimSpace(s) != s {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		if strings.Contains(s, "_") || strings.Contains(s, ".") || strings.Contains(strings.ToLower(s), "x") {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		if _, err := strconv.Atoi(s); err != nil {
			return fmt.Errorf("invalid height specification: %q", s)
		}
		return nil
	}
}

func loadJSONConfig(path string) (Config, error) {
	var cfg Config
	data, err := os.ReadFile(path)
	if err != nil {
		return cfg, fmt.Errorf("failed to open file %s: %v", path, err)
	}
	// Handle empty file? Original for empty file? Empty JSON file with 0 bytes gave "EOF"? Let's see: empty file with --rcfile empty.json (0 bytes) gave? We tested empty file? Actually we tested empty file? For empty.json (0 bytes) with --rcfile, what happens? Let's assume it gives EOF error.
	// Use json.Unmarshal
	if len(strings.TrimSpace(string(data))) == 0 {
		// Go's json for empty gives "EOF"
		return cfg, fmt.Errorf("failed to decode JSON: EOF")
	}
	if err := json.Unmarshal(data, &cfg); err != nil {
		return cfg, fmt.Errorf("failed to decode JSON: %v", err)
	}
	// Validate OnCancel if present? Original validates OnCancel during decode (for "bogus", error is "failed to decode JSON: invalid OnCancel value...").
	// Our Config.OnCancel is plain string, so "bogus" will succeed in Unmarshal, need to validate here and return with same prefix.
	if cfg.OnCancel != "" && cfg.OnCancel != "success" && cfg.OnCancel != "error" {
		return cfg, fmt.Errorf("failed to decode JSON: invalid OnCancel value %q: must be \"success\" or \"error\"", cfg.OnCancel)
	}
	// Validate Layout if present? Original for {"Layout":"bogus"} gives "failed to read config file: invalid layout type: bogus" (without decode prefix, directly under read).
	// That validation happens after decode, but still under "failed to read config file", not "failed to decode".
	// We'll handle Layout validation separately in caller to get correct prefix.
	return cfg, nil
}

