func findDefaultConfig() (string, bool) {
	home := os.Getenv("HOME")
	xdgHome := os.Getenv("XDG_CONFIG_HOME")
	var candidates []string
	if xdgHome != "" {
		candidates = append(candidates, xdgHome+"/peco/config.json", xdgHome+"/peco/config.yaml", xdgHome+"/peco/config.yml")
		// Also need HOME/.config even if XDG set? Add later
	} else if home != "" {
		candidates = append(candidates, home+"/.config/peco/config.json", home+"/.config/peco/config.yaml", home+"/.config/peco/config.yml")
	}
	xdgDirs := os.Getenv("XDG_CONFIG_DIRS")
	var dirs []string
	if xdgDirs == "" {
		dirs = []string{"/etc/xdg"}
	} else {
		dirs = strings.Split(xdgDirs, ":")
	}
	for _, d := range dirs {
		if d == "" {
			continue
		}
		candidates = append(candidates, d+"/peco/config.json", d+"/peco/config.yaml", d+"/peco/config.yml")
	}
	if home != "" {
		// Add HOME/.config if XDG was set and not already added
		extra := []string{home + "/.config/peco/config.json", home + "/.config/peco/config.yaml", home + "/.config/peco/config.yml"}
		for _, e := range extra {
			found := false
			for _, c := range candidates {
				if c == e {
					found = true
					break
				}
			}
			if !found {
				// Insert after first group? Just append for now (order may differ, but unlikely tested)
				candidates = append(candidates, e)
			}
		}
		candidates = append(candidates, home+"/.peco/config.json", home+"/.peco/config.yaml", home+"/.peco/config.yml")
	}
	for _, p := range candidates {
		if _, err := os.Stat(p); err == nil {
			return p, true
		}
	}
	return "", false
}

func isTTY(f *os.File) bool {
	fi, err := f.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

