				} else {
					excluded = re.MatchString(stripped)
				}
			case "IRegexp":
				re, err := regexp.Compile("(?i)" + pat)
				if err != nil {
					excluded = false
				} else {
					excluded = re.MatchString(stripped)
				}
			case "Fuzzy":
				// Negatives always insensitive
				excluded = fuzzyMatch(stripped, pat, true)
			default:
				excluded = strings.Contains(strings.ToLower(stripped), strings.ToLower(pat))
			}
			if excluded {
				matched = false
				break
			}
		}
		if matched {
			out = append(out, line)
		}
	}
	return out
