func parseSimpleYAML(content string) (Config, error) {
	var cfg Config
	// Very simple YAML parser for peco config: handles top-level key: value where value is string, bool, int, or nested? For nested like Keymap, CustomFilter, etc., ignore? Actually need to handle nested for valid configs to work.
