		// Handle value: if empty, then nested? For now, ignore nested (e.g., "Keymap:" with following indented lines). We'll just skip if val empty and next lines indented? Actually need to handle nested maps like CustomFilter, Keymap, etc. For simplicity, ignore nested for now (treat as empty).
		// If valStr is quoted string, unquote
		if valStr == "" {
			// Nested, ignore for now (could be Keymap, etc.)
			continue
		}
		// Unquote if needed
		var v interface{}
		// Try to parse valStr as JSON value (for strings, bools, numbers)
		// YAML plain strings like CaseSensitive without quotes should be treated as string "CaseSensitive"
		// YAML quoted "[yaml]" with quotes should be string without quotes
		// Simplest: if valStr starts with '"' and ends with '"', unquote via json
		// Else if valStr is "true"/"false"/number, parse accordingly, else treat as string
		switch key {
		case "Prompt", "InitialFilter", "Layout", "Height", "SelectionPrefix", "OnCancel":
			// String fields
			if strings.HasPrefix(valStr, "\"") && strings.HasSuffix(valStr, "\"") && len(valStr) >= 2 {
				var s string
				if err := json.Unmarshal([]byte(valStr), &s); err == nil {
					v = s
				} else {
					v = valStr
				}
			} else if strings.HasPrefix(valStr, "'") && strings.HasSuffix(valStr, "'") && len(valStr) >= 2 {
				v = valStr[1 : len(valStr)-1]
			} else {
				v = valStr
			}
			switch key {
			case "Prompt":
				cfg.Prompt = v.(string)
			case "InitialFilter":
				cfg.InitialFilter = v.(string)
			case "Layout":
				cfg.Layout = v.(string)
			case "Height":
				cfg.Height = v.(string)
			case "SelectionPrefix":
				cfg.SelectionPrefix = v.(string)
			case "OnCancel":
				cfg.OnCancel = v.(string)
			}
		case "StickySelection", "FuzzyLongestSort", "SuppressStatusMsg", "ANSI":
			// Bool
			if valStr == "true" {
				v = true
			} else if valStr == "false" {
				v = false
			} else {
				// Try unquoted? Return error?
				return cfg, fmt.Errorf("yaml: invalid bool %q", valStr)
			}
			switch key {
