				} else {
					excluded = re.MatchString(stripped)
				}
			case "Fuzzy":
				excluded = fuzzyMatch(stripped, pat, true)
			default:
				excluded = strings.Contains(strings.ToLower(stripped), strings.ToLower(pat))
			}
			if excluded {
				matched = false
				break
			}
		}
		if matched {
			out = append(out, pr)
		}
	}
