	buf := make([]byte, 1)
	n, err := tty.Read(buf)
	if err != nil || n == 0 {
		return Key{}, err
	}
	b := buf[0]
	// Enter? 13 (\r) or 10 (\n)? In raw mode, Enter sends 13? Handle both.
	if b == 13 || b == 10 {
		return Key{Special: "Enter"}, nil
	}
	if b == 27 {
		// Esc or escape sequence? Try to peek next bytes with timeout
		// Set non-blocking read with timeout 50ms
		// Use goroutine + select with timeout
		type res struct {
			b byte
			ok bool
		}
		ch := make(chan res, 1)
		go func() {
			nb := make([]byte, 1)
			n, err := tty.Read(nb)
			if err != nil || n == 0 {
				ch <- res{ok: false}
				return
			}
			ch <- res{b: nb[0], ok: true}
		}()
		select {
		case r := <-ch:
			if !r.ok {
				return Key{Special: "Esc"}, nil
			}
			if r.b == '[' {
				// CSI sequence, read more
				// Read until letter or ~?
				// For arrows: [A (up), [B (down), [C (right), [D (left)
				// For PgUp/Dn: [5~, [6~, Home: [H, End: [F, Delete: [3~, Insert: [2~
				// Read next byte
				nb2 := make([]byte, 1)
				// Blocking read for next (should be available quickly)
				// Use timeout again?
				done := make(chan byte, 1)
				go func() {
					n, _ := tty.Read(nb2)
					if n > 0 {
						done <- nb2[0]
					} else {
						done <- 0
					}
				}()
				select {
				case b2 := <-done:
					if b2 == 'A' {
						return Key{Special: "Up"}, nil
					} else if b2 == 'B' {
						return Key{Special: "Down"}, nil
					} else if b2 == 'C' {
						return Key{Special: "Right"}, nil
					} else if b2 == 'D' {
						return Key{Special: "Left"}, nil
					} else if b2 == 'H' {
						return Key{Special: "Home"}, nil
					} else if b2 == 'F' {
						return Key{Special: "End"}, nil
					} else if b2 >= '0' && b2 <= '9' {
						// Extended like [5~, [6~, [3~, etc. Read until ~ or letter
						seq := string([]byte{b2})
						for {
							nb3 := make([]byte, 1)
							n, _ := tty.Read(nb3)
							if n == 0 {
								break
							}
							seq += string(nb3[0])
							if nb3[0] == '~' || (nb3[0] >= 'A' && nb3[0] <= 'Z') || (nb3[0] >= 'a' && nb3[0] <= 'z') {
								break
							}
						}
						if seq == "5~" {
							return Key{Special: "PgUp"}, nil
						} else if seq == "6~" {
							return Key{Special: "PgDn"}, nil
						} else if seq == "3~" {
							return Key{Special: "Delete"}, nil
						} else if seq == "2~" {
							return Key{Special: "Insert"}, nil
						} else if seq == "1~" {
							return Key{Special: "Home"}, nil
						} else if seq == "4~" {
							return Key{Special: "End"}, nil
						} else {
							return Key{Special: "Unknown"}, nil
						}
					} else {
						return Key{Special: "Unknown"}, nil
					}
				case <-time.After(50 * time.Millisecond):
					return Key{Special: "Esc"}, nil
				}
			} else if r.b == 'O' {
				// SS3 sequences: OP (F1), etc. Ignore
				return Key{Special: "Unknown"}, nil
			} else {
				// Alt+key? e.g., Esc + x for M-x? In peco, M- prefix for Alt. So Esc followed by char means Alt+char.
				// Return Alt modified key
				return Key{Rune: rune(r.b), Alt: true}, nil
			}
		case <-time.After(50 * time.Millisecond):
			return Key{Special: "Esc"}, nil
		}
	}
	if b == 127 || b == 8 {
		return Key{Special: "Backspace"}, nil
	}
	if b == 9 {
		return Key{Special: "Tab"}, nil
	}
	if b < 32 {
		// Ctrl keys: 1-26 correspond to C-a..C-z, 0 is C-Space, 28-31 etc.
		if b == 0 {
			return Key{Rune: 0, Ctrl: false, Special: "C-Space"}, nil
		}
		// Map 1-26 to C-a..C-z
		if b >= 1 && b <= 26 {
			r := rune('a' + b - 1)
			// Special handling for C-m (13? Actually C-m is 13, already handled as Enter), C-i (9, Tab), C-[ (27, Esc), etc.
			// For others, return Ctrl key
			return Key{Rune: r, Ctrl: true}, nil
		}
		// Other controls like 28-31?
		return Key{Rune: rune(b), Ctrl: true}, nil
	}
	// Printable (including space 32, up to 126, and UTF-8 multi-byte? For UTF-8, first byte >=128, need to read continuation bytes)
	if b < 128 {
		return Key{Rune: rune(b)}, nil
	}
	// UTF-8 multi-byte: determine length
	var need int
	if b>>5 == 0x6 {
		need = 1
	} else if b>>4 == 0xE {
		need = 2
	} else if b>>3 == 0x1E {
		need = 3
	} else {
		return Key{Rune: rune(b)}, nil
	}
	extra := make([]byte, need)
	for i := 0; i < need; i++ {
		nb := make([]byte, 1)
		n, _ := tty.Read(nb)
		if n == 0 {
			break
		}
		extra[i] = nb[0]
	}
	full := append([]byte{b}, extra...)
	r := []rune(string(full))
	if len(r) > 0 {
		return Key{Rune: r[0]}, nil
	}
	return Key{Rune: rune(b)}, nil
}

